mapper.insert:
INSERT IGNORE INTO saved_support_program (account_id, support_program_id, saved_at)
SELECT #{accountId}, program.id, #{savedAt}
FROM support_program program
WHERE program.source_code = #{sourceCode}
  AND program.source_program_id = #{sourceProgramId}
  AND program.is_source_present = TRUE

mapper.delete:
DELETE saved
FROM saved_support_program saved
JOIN support_program program ON program.id = saved.support_program_id
WHERE saved.account_id = #{accountId}
  AND program.source_code = #{sourceCode}
  AND program.source_program_id = #{sourceProgramId}

mapper.select:
SELECT

FROM saved_support_program saved
JOIN support_program program ON program.id = saved.support_program_id
WHERE saved.account_id = #{accountId}
  AND program.source_code = #{sourceCode}
  AND program.source_program_id = #{sourceProgramId}
  AND program.is_source_present = TRUE

mapper.update:
UPDATE saved_support_program SET source_prefetch_next_publish_at = #{retryAt}
WHERE id = #{id} AND source_prefetch_status = 'PENDING'
  AND (source_prefetch_next_publish_at IS NULL OR source_prefetch_next_publish_at <= #{now})

UPDATE saved_support_program
SET source_prefetch_status = 'PUBLISHED', source_prefetch_updated_at = #{now}
WHERE id = #{id} AND source_prefetch_status = 'PENDING'

UPDATE saved_support_program
SET source_prefetch_status = 'PENDING', source_prefetch_next_publish_at = NULL
WHERE source_prefetch_status = 'PUBLISHED' AND source_prefetch_updated_at < #{before}

UPDATE saved_support_program
SET source_prefetch_status = 'PENDING', source_prefetch_next_publish_at = NULL
WHERE source_prefetch_status = 'DONE' AND source_prefetch_updated_at < #{before}
ORDER BY source_prefetch_updated_at LIMIT ${limit}
